// Bundled Q2 browser demo previews for both HTTP and file://.
for (const [id, encoded] of Object.entries({
  "audio-tidal": "",
  "audio-northline": "",
  "audio-afterhours": "",
  "audio-sundial": "",
  "audio-softsignal": "",
  "audio-fieldnotes": "",
  "audio-copper": "",
  "audio-pinksky": "",
  "audio-radio": "",
  "audio-spoken-0": "",
  "audio-spoken-1": "",
  "audio-spoken-2": "",
  "audio-spoken-3": "",
  "audio-spoken-4": "",
  "audio-spoken-5": ""
})) {
  const asset = document.createElement("script");
  asset.id = id;
  asset.type = "audio/mpeg";
  asset.textContent = encoded;
  document.body.append(asset);
}
